from h import P
R=[
(9956832,"एयर फ्रायर पिटा चिप्स","एयर फ्रायर पिटा चिप्स एक सीधा-सादा और स्वादिष्ट नाश्ता है जो 10 मिनट से भी कम में तैयार हो जाता है!","2 सर्विंग","1 सर्विंग",
["2 होल व्हीट पिटा ब्रेड या अपनी पसंद की","1 बड़ा चम्मच एक्वाफाबा या पसंद हो तो अपनी पसंद का तेल","½ छोटा चम्मच लहसुन पाउडर","½ छोटा चम्मच सूखा अजमोद (पार्सली)","¼ छोटा चम्मच समुद्री नमक"],
["अपने पिटा को 8 तिकोने टुकड़ों में काटें। इसके लिए पिज़्ज़ा कटर इस्तेमाल करना जल्दी का तरीका है। फिर बाकी सामग्री एक छोटे बाउल में मिलाएं।","मसाले के मिश्रण को अपने पिटा के टुकड़ों के ऊपर ब्रश से लगाएं। फिर उन्हें अपनी एयर फ्रायर की टोकरी में सजाएं। (अगर वे थोड़े एक-दूसरे पर आ जाएं तो कोई बात नहीं।)","350°F/176°C पर नरम चिप्स के लिए 3-4 मिनट या ज़्यादा कुरकुरे चिप्स के लिए 5-7 मिनट एयर फ्राई करें। उन्हें बार-बार देखते रहें और मनचाहा पकाव आने पर निकाल लें। आनंद लें!"],
["अलग-अलग एयर फ्रायर मॉडल अलग गति से पकाते हैं। अपने चिप्स को बार-बार देखें, 3 मिनट से शुरू करके। नरम चिप्स के लिए लगभग 3-4 मिनट एयर फ्राई करें।","कुरकुरे चिप्स के लिए लगभग 5-7 मिनट एयर फ्राई करें।","पिटा के तिकोनों का आपकी फ्रायर की टोकरी में थोड़ा एक-दूसरे पर आना कोई समस्या नहीं है। हालांकि, उन्हें पूरी तरह एक-दूसरे पर न रखें। ज़रूरत हो तो कई बैच में पकाएं। नोट: बाद के बैच जल्दी पकेंगे।"],
[]),
(9957284,"एयर फ्रायर नाशपाती","मीठी, नरम, कैरामेल जैसी, बेहद स्वादिष्ट एयर फ्रायर नाशपाती! अपनी पकी नाशपातियों को एक सेहतमंद मिठाई में बदलें जो पूरे परिवार को पसंद आएगी।","2","1 सर्विंग",
["2 बार्टलेट नाशपाती, पकी हुई","1.5 बड़े चम्मच मेपल सिरप","1 छोटा चम्मच दालचीनी","⅛ छोटा चम्मच जायफल","वैकल्पिक टॉपिंग::ग्रेनोला","वैकल्पिक टॉपिंग::नारियल के फ्लेक्स","वैकल्पिक टॉपिंग::कटे हुए पीकन या अखरोट"],
["नाशपाती को धोकर छील लें। (या पसंद हो तो छिलके रहने भी दे सकते हैं।) फिर उन्हें चार टुकड़ों में काटें, बीज खुरचकर निकालें और बीच का हिस्सा हटा दें। एक छोटे मिक्सिंग बाउल में रखें।","ऊपर से मेपल सिरप, दालचीनी और जायफल डालें और बराबर लगने तक धीरे से मिलाएं।","लगे हुए नाशपाती के टुकड़ों को चम्मच से एक परत में अपनी टोकरी में रखें और 380 डिग्री F (190 C) पर 8-12 मिनट एयर फ्राई करें, जब तक वे सुनहरे और कैरामेलाइज़्ड न हो जाएं। उन्हें उलटें नहीं!","नाशपाती को टोकरी से सावधानी से निकालें और ग्रेनोला, नारियल के फ्लेक्स और कटे हुए पीकन या अखरोट की टॉपिंग के साथ परोसें। आनंद लें।"],
["सबसे मीठे, रसीले नतीजों के लिए पकी हुई नाशपाती इस्तेमाल करें। बराबर पकने के लिए नाशपाती के स्लाइस को बराबर आकार के टुकड़ों में काटने की कोशिश करें। अगर कुछ टुकड़े बड़े होंगे, तो वे उतने नरम नहीं होंगे, हालांकि फिर भी स्वादिष्ट होंगे। नाशपाती को टोकरी में उलटें नहीं। उन्हें टूटने से बचाने के लिए सावधानी से चम्मच से टोकरी में रखें और एक परत में सजाएं। अगर बाउल के तले में बचा हुआ मैरिनेड है, तो उसे नाशपाती पकने के बाद उन पर ग्लेज़ की तरह डालने के लिए अलग रखें। इस असंभव घटना में कि कुछ बच जाए, उसे फ्रिज में बंद डिब्बे में 2-3 दिन रखें।"],
[]),
(9957667,"इंस्टेंट पॉट बटरनट स्क्वैश सूप (या चूल्हे पर)","मलाईदार, गरमाहट देने वाला और बेहद मुंह में पानी लाने वाला इंस्टेंट पॉट बटरनट स्क्वैश सूप!","6 सर्विंग","1 सर्विंग",
["1 पीला प्याज़, कटा हुआ","1 बड़ी गाजर, छिली और कटी हुई","1 बड़ी अजवाइन की डंडी, कटी हुई","2 पाउंड बटरनट स्क्वैश, छिला हुआ और 1 इंच के टुकड़ों में कटा हुआ (लगभग 5 कप टुकड़े)","1 पाउंड पीले आलू, छिले हुए और 1 इंच के टुकड़ों में कटे हुए (लगभग 2 कप टुकड़े)","1 बड़ा ग्रैनी स्मिथ सेब, टुकड़ों में कटा हुआ, बीच का हिस्सा और बीज निकाले हुए","5 कप कम सोडियम वाला सब्ज़ी का शोरबा","½ छोटा चम्मच पिसा जायफल","¼ छोटा चम्मच पिसी अदरक","¼ छोटा चम्मच पिसी दालचीनी","1 कप बिना चीनी वाला काजू का दूध या अपनी पसंद का दूध","नमक + काली मिर्च स्वादानुसार","वैकल्पिक::सजावट के लिए काजू क्रीम"],
["इंस्टेंट पॉट की विधि::अपने इंस्टेंट पॉट पर सॉते फ़ंक्शन चुनें और प्याज़, गाजर और अजवाइन को 2-3 बड़े चम्मच पानी के साथ डालें। नरम होने तक, लगभग 5 मिनट भूनें।","इंस्टेंट पॉट की विधि::दूध को छोड़कर बाकी सारी सामग्री डालें और एक बार चलाएं। ढक्कन बंद करें और वाल्व को सीलिंग की स्थिति में रखें। अब 6 मिनट के लिए प्रेशर कुक पर सेट करें (प्रेशर बनने में लगभग 15 मिनट लगेंगे)। टाइमर पूरा होने पर, स्टीम वाल्व से तुरंत भाप निकाल दें और सुरक्षित होने पर ढक्कन खोलें।","इंस्टेंट पॉट की विधि::सूप को पीसने के लिए इमर्शन ब्लेंडर का इस्तेमाल करें। (या सावधानी से कई बार में ब्लेंडर में डालकर पीसें।) पौधों से बना दूध मिलाएं और स्वादानुसार नमक और काली मिर्च डालें। फिर चाहें तो काजू क्रीम से सजाकर परोसें।","चूल्हे पर बनाने की विधि::प्याज़, गाजर और अजवाइन को 2-3 बड़े चम्मच पानी के साथ एक बड़े बर्तन में डालें और नरम होने तक, लगभग 5 मिनट भूनें।","चूल्हे पर बनाने की विधि::दूध को छोड़कर बाकी सारी सामग्री डालें और अच्छी तरह मिलाएं। उबाल आने दें और फिर आंच को धीमा करें और स्क्वैश और आलू के कांटे से आसानी से छिदने तक, लगभग 20-25 मिनट पकाएं।","चूल्हे पर बनाने की विधि::आंच बंद करें, और इमर्शन ब्लेंडर से अपने सूप को पीस लें। (या सावधानी से कई बार में ब्लेंडर में डालकर पीसें।) पौधों से बना दूध मिलाएं और स्वादानुसार नमक और काली मिर्च डालें। फिर चाहें तो काजू क्रीम से सजाकर परोसें।"],
["स्वाद की गहराई बढ़ाने के लिए (और अगर समय हो) अपने बटरनट स्क्वैश को आधा काटें और गूदे वाली तरफ नीचे करके कांटे से आसानी से छिदने तक भूनें। फिर भुने हुए स्क्वैश को अपने सूप के बर्तन में डालें और साथ में पीस लें। समय बचाने के लिए, आप अपनी किराने की दुकान से पहले से कटा बटरनट स्क्वैश खरीद सकते हैं। आपको लगभग 5 कप कटे स्क्वैश की ज़रूरत होगी। नट-मुक्त बनाने के लिए, काजू की जगह सोया दूध, ओट दूध या नारियल का दूध (डिब्बे वाला नहीं, कार्टन वाला) इस्तेमाल करें। बचा हुआ बंद डिब्बे में फ्रिज में 3-5 दिन ठीक रहता है या फ्रीज़र-सुरक्षित डिब्बे में हवाबंद करके 3 महीने तक फ्रीज़ करें।"],
[]),
(9959942,"तीन स्वादों में एयर फ्रायर मूंगफली! [तेल की ज़रूरत नहीं]","एयर फ्रायर मूंगफली के तीन शानदार स्वाद जो ऐसे लगते हैं जैसे भुने गए हों, लेकिन बनाने में कहीं ज़्यादा तेज़ हैं।","4 सर्विंग","1 सर्विंग",
["1 कप कच्ची मूंगफली, बिना नमक की","1 बड़ा चम्मच एक्वाफाबा या बिना खास स्वाद वाला तेल","नमक + काली मिर्च वाली भुनी मूंगफली::½ छोटा चम्मच समुद्री नमक","नमक + काली मिर्च वाली भुनी मूंगफली::⅛ छोटा चम्मच काली मिर्च","स्मोकी बीबीक्यू भुनी मूंगफली::½ छोटा चम्मच स्मोक्ड पपरिका","स्मोकी बीबीक्यू भुनी मूंगफली::¼ छोटा चम्मच लहसुन पाउडर","स्मोकी बीबीक्यू भुनी मूंगफली::¼ छोटा चम्मच समुद्री नमक","स्मोकी बीबीक्यू भुनी मूंगफली::⅛ छोटा चम्मच काली मिर्च","चुरोस भुनी मूंगफली::1 छोटा चम्मच नारियल चीनी या ब्राउन शुगर","चुरोस भुनी मूंगफली::½ छोटा चम्मच दालचीनी"],
["कच्ची मूंगफली को अपनी एयर फ्रायर की टोकरी में एक परत में रखें और 350°F/177°C पर 6-8 मिनट एयर फ्राई करें, बीच में एक बार मिलाएं।","इसी बीच, एक छोटे मिक्सिंग बाउल में 1 बड़ा चम्मच एक्वाफाबा और अपनी पसंद का मसाला मिश्रण डालें। अच्छी तरह मिलाएं।","भुनी हुई मूंगफली को मसाले वाले बाउल में डालें और बराबर लगने तक अच्छी तरह मिलाएं। फिर उन्हें वापस टोकरी में रखें और सुनहरी होने तक 2-4 मिनट और एयर फ्राई करें, लेकिन जलने से बचाने के लिए ध्यान से देखते रहें।","फिर एयर फ्राई की हुई मूंगफली को एक बाउल में डालें और खाने से पहले कुछ मिनट ठंडा होने दें।"],
["पकाने की शुरुआत से ही मूंगफली में मसाला न डालें, वरना मसाले जलने लग सकते हैं। अगर कई बैच बना रहे हैं (जो आपको बनाने चाहिए, ताकि सारे स्वाद आज़मा सकें 😉), तो ध्यान रखें कि बाद के बैच थोड़े जल्दी पकेंगे, इसलिए ध्यान से देखें। पोषण संबंधी जानकारी नमक और काली मिर्च स्वाद वाली एयर फ्राई की हुई मूंगफली के ¼ कप के एक सर्विंग साइज़ की है। बचा हुआ बंद डिब्बे में कमरे के तापमान पर 1 हफ्ते तक रखें।"],
[]),
(9964071,"वीगन तोरी (ज़ुकीनी) कुकीज़ [ओटमील]","नरम, चबाने लायक, और सब्ज़ियों से भरी, ये वीगन तोरी (ज़ुकीनी) कुकीज़ ज़रूर आज़माने लायक हैं!","24 कुकीज़","1 सर्विंग",
["गीली सामग्री::3 पके केले, मसले हुए (1 ¼ कप मसले हुए)","गीली सामग्री::⅓ कप प्राकृतिक पीनट बटर, चिकना या क्रंची","गीली सामग्री::¼ कप मेपल सिरप","गीली सामग्री::2 कप कद्दूकस की हुई तोरी (ज़ुकीनी), लगभग 1 मध्यम तोरी (अतिरिक्त नमी निचोड़ दें)","सूखी सामग्री::1 कप रोल्ड ओट्स, पसंद हो तो ग्लूटेन-मुक्त","सूखी सामग्री::¼ कप हेम्प हार्ट्स","सूखी सामग्री::¼ कप अलसी के बीज या पिसे हुए अलसी के बीज","सूखी सामग्री::1 छोटा चम्मच दालचीनी","सूखी सामग्री::1 छोटा चम्मच बेकिंग पाउडर"],
["केलों को एक बड़े मिक्सिंग बाउल में मसलें। फिर पीनट बटर और मेपल सिरप डालें और अच्छी तरह मिलाएं। इसके बाद, सूखी सामग्री डालें और मिलने तक मिलाएं। घोल गाढ़ा होगा।","कद्दूकस की हुई तोरी उसी बाउल में मिलाएं और घोल को 10 मिनट रहने दें।","अपने ओवन को 350℉/176℃ पर पहले से गरम करें और एक बड़ी बेकिंग शीट पर बेकिंग पेपर बिछाएं।","फिर घोल को अपनी ट्रे पर निकालें और कुकीज़ को आकार दें और चपटा करें, क्योंकि वे ओवन में ज़्यादा नहीं फैलेंगी।","18-22 मिनट बेक करें, जब तक सुनहरी भूरी न हो जाएं। फिर उन्हें ओवन से निकालें, और जमने के लिए 5-10 मिनट ठंडा होने दें।"],
["नखरीले खाने वालों के लिए, तोरी को कद्दूकस करने से पहले छील लें ताकि उसका चटकीला हरा छिलका छिप जाए। कद्दूकस की हुई तोरी को घोल में डालने से पहले बाउल या अपने किचन सिंक के ऊपर निचोड़ लें। घोल गाढ़ा होगा लेकिन तोरी कुकीज़ में नमी डालेगी। नट-मुक्त के लिए पीनट बटर की जगह सोया बटर या सूरजमुखी बटर इस्तेमाल करें। बची हुई कुकीज़ कमरे के तापमान पर 2 दिन, या फ्रिज में 6 दिन तक ठीक रहेंगी। पहले कमरे के तापमान पर ठंडा करने के बाद उन्हें हवाबंद करके 3 महीने तक फ्रीज़ करें।"],
[]),
(9964694,"वीगन क्रेमा फ्रेस्का उर्फ वीगन क्रेम फ्रेश","मलाईदार, स्वादिष्ट वीगन क्रेमा फ्रेस्का (उर्फ क्रेम फ्रेश) बनाने के लिए, जिसे आप हर चीज़ पर डाल सकें, आपको बस 4 सामग्री और 5 मिनट चाहिए!","8 सर्विंग","1 सर्विंग",
["1 कप कच्चे काजू","½-¾ कप ताज़ा पानी, मुझे आधा कप और 2 बड़े चम्मच पसंद है","¼ कप नींबू का रस, लगभग 1 बड़ा नींबू या 2 छोटे","½ छोटा चम्मच समुद्री नमक"],
["सारी सामग्री Vitamix जैसे हाई-स्पीड ब्लेंडर में डालें और चिकना और मलाईदार होने तक चलाएं। आधा कप पानी से शुरू करें और मनचाहा गाढ़ापन आने तक एक बार में 1-2 बड़े चम्मच और डालें। (मुझे आधा कप और दो बड़े चम्मच बिल्कुल सही लगते हैं।)","भुट्टे, नाचोस, टैको, सूप या चिली के साथ या सलाद के ऊपर परोसें।"],
["अगर आपके पास हाई-स्पीड ब्लेंडर नहीं है, तो काजू को पीसने से पहले 30 मिनट खौलते गरम पानी में भिगोएं, और फिर छान लें। भिगोने से वे नरम हो जाते हैं, जिससे उन्हें पीसना आसान हो जाता है। इस्तेमाल से पहले अपनी क्रेमा को फ्रिज में रखें क्योंकि यह ठंडी होने पर सबसे अच्छी लगती है। अगर समय न हो, तो ताज़ा बनी हुई भी बहुत बढ़िया लगती है। नट-मुक्त के लिए, आप काजू की जगह कच्चे सूरजमुखी के बीज या पेपिटास इस्तेमाल कर सकते हैं, नतीजा लगभग वैसा ही रहेगा। बिना नमक वाले का इस्तेमाल करें या नमक छोड़ दें। बचा हुआ फ्रिज में 5 दिन तक ठीक रहता है, या 3 महीने तक फ्रीज़ करें।"],
[]),
(9966381,"वीगन बीन सलाद","एक वीगन बीन सलाद जो भरपूर और मुंह में पानी लाने वाला स्वादिष्ट है!","6 सर्विंग","1 सर्विंग",
["सलाद के लिए::15 औंस का 1 डिब्बा छोले, छाने + धुले हुए (लगभग 1.5 कप)","सलाद के लिए::15 औंस का 1 डिब्बा काली बीन्स, छानी + धुली हुई (लगभग 1.5 कप)","सलाद के लिए::15 औंस का 1 डिब्बा लाल राजमा, छाना + धुला हुआ (लगभग 1.5 कप)","सलाद के लिए::1.5 कप कटा हुआ खीरा, लगभग आधा लंबा खीरा","सलाद के लिए::¼ कप कटा हुआ लाल प्याज़","सलाद के लिए::1 एवोकाडो, कटा हुआ","सलाद के लिए::½ कप तुलसी की पत्तियां, बारीक कटी हुई","ड्रेसिंग के लिए::¼ कप नींबू का रस, लगभग 1 मध्यम नींबू","ड्रेसिंग के लिए::2 बड़े चम्मच बाल्सामिक सिरका","ड्रेसिंग के लिए::1 बड़ा चम्मच मेपल सिरप","ड्रेसिंग के लिए::नमक + काली मिर्च स्वादानुसार"],
["बीन्स को छानकर धो लें, सारी सब्ज़ियां काट लें, और उन्हें एक बड़े बाउल में डालें।","एक दूसरे छोटे बाउल में सलाद ड्रेसिंग की सामग्री मिलाएं। फिर ड्रेसिंग को सलाद पर डालें और बराबर लगने तक अच्छी तरह मिलाएं। तुरंत खाएं या परोसने से पहले 1 घंटा फ्रिज में रखें।"],
["इस व्यंजन को परोसने से लगभग 1 घंटा पहले बनाने की योजना बनाएं क्योंकि यह ठंडा होने पर सबसे अच्छा लगता है।","यह सलाद बनने के उसी दिन सबसे अच्छा लगता है, लेकिन बचा हुआ फ्रिज में 2-3 दिन ठीक रहता है,"],
[]),
(9966537,"सेहतमंद केला अखरोट स्मूदी","प्रोटीन से भरपूर यह केला अखरोट स्मूदी आपकी सुबह की शुरुआत का या दोपहर में बेहद ज़रूरी ऊर्जा देने का एकदम सही तरीका है!","2 सर्विंग","1 सर्विंग",
["2 कप बिना चीनी वाला बादाम का दूध या अपनी पसंद का दूध","⅓ कप अखरोट","2 जमे हुए केले","¼ छोटा चम्मच दालचीनी"],
["सारी सामग्री ब्लेंडर में डालें और चिकना होने तक चलाएं। आनंद लें!"],
["बहुत ज़रूरी न हो तो ताज़े केले का विकल्प न लें। जमा हुआ केला सच में सबसे अच्छा काम करता है। अगर आपके पास जमे हुए केले नहीं हैं, तो आप ताज़े केलों को छीलकर काट सकते हैं और 30-60 मिनट फ्रीज़ कर सकते हैं। उन्हें पहले काटना न भूलें ताकि वे जल्दी जम जाएं। ताज़े केले इस्तेमाल करने के लिए, अगर आपके पास उन्हें फ्रीज़ करने का समय नहीं है, तो समान नतीजों के लिए स्मूदी में मुट्ठी भर बर्फ के टुकड़े भी डालें। सुनिश्चित करें कि आपके केले बहुत पके हुए हों। यहां सारी मिठास आपके केलों से आ रही है, इसलिए जितने पके हों उतना बेहतर। फ्रीज़ करने से पहले भूरे धब्बों वाले छिलके के केले चुनें। ज़्यादा मीठी स्मूदी के लिए, आप एक छोटा चम्मच शुद्ध मेपल सिरप या 2-3 बीज निकाले खजूर डाल सकते हैं। अगर आपके पास अखरोट नहीं हैं, तो बादाम, हेज़लनट या पीकन का विकल्प ले सकते हैं। सबसे अच्छे नतीजों के लिए, हाई-स्पीड ब्लेंडर इस्तेमाल करें, लेकिन अगर आपके पास नहीं है, तो अखरोट को लगभग 10-15 मिनट ताज़े पानी में भिगोएं और फिर छान लें। इससे आपके ब्लेंडर के लिए उन्हें पीसना आसान होगा, बिना किरकिरापन छोड़े। लगभग 3.5 कप बनता है।"],
[]),
]
P(11,R)
